SELECT v.*, c.category_name FROM venue v LEFT JOIN venue_category c ON v.category_id = c.id
AND v.venue_name LIKE CONCAT('%', #{venueName}, '%')
AND v.venue_address LIKE CONCAT('%', #{venueAddress}, '%')
AND v.category_id = #{categoryId}
AND v.status = #{status}
ORDER BY v.created_at DESC

